using System.Collections.Generic;public class Solution{bool Pal(string s,int l,int r){while(l<r)if(s[l++]!=s[r--])return false;return true;}string Rev(string s){char[]a=s.ToCharArray();System.Array.Reverse(a);return new string(a);}public IList<IList<int>> PalindromePairs(string[]w){var m=new Dictionary<string,int>();for(int i=0;i<w.Length;i++)m[w[i]]=i;var o=new List<IList<int>>();for(int i=0;i<w.Length;i++)for(int k=0;k<=w[i].Length;k++){if(Pal(w[i],0,k-1)){string x=Rev(w[i].Substring(k));if(m.ContainsKey(x)&&m[x]!=i)o.Add(new List<int>{m[x],i});}if(k<w[i].Length&&Pal(w[i],k,w[i].Length-1)){string x=Rev(w[i].Substring(0,k));if(m.ContainsKey(x)&&m[x]!=i)o.Add(new List<int>{i,m[x]});}}return o;}}
